{
  "missing_information": [
    {
      "category": "Meeting Trigger",
      "gap": "What initiates a vendor meeting — fixed schedule, operational issue, or ad hoc request",
      "why_it_matters": "Determines whether the workflow start event can be automated or predicted, and how to model the process entry point"
    },
    {
      "category": "Roles and Ownership",
      "gap": "Which organizational roles attend the meeting and who is accountable for organizing it and producing the summary",
      "why_it_matters": "Essential for assigning swim lanes, responsibilities, and handoff points in the process model"
    },
    {
      "category": "Summary Output Format",
      "gap": "What the meeting summary looks like as a finished artifact and who receives it",
      "why_it_matters": "Defines the output artifact of a key workflow step and its distribution, which affects automation and standardization potential"
    },
    {
      "category": "Action Item Recording",
      "gap": "How action items are captured, assigned, and stored — including owner, due date, priority, and the tool used",
      "why_it_matters": "Central to understanding how the follow-up subprocess is structured and whether it can be automated or integrated with a task system"
    },
    {
      "category": "Follow-up Mechanism",
      "gap": "How follow-up on action items is conducted and how overdue items are escalated or reminded",
      "why_it_matters": "Reveals whether the follow-up loop is manual or systematic, and identifies gaps that automation could address"
    },
    {
      "category": "Workflow Completion Criteria",
      "gap": "What condition marks the entire workflow as complete",
      "why_it_matters": "Needed to define the process end event and measure cycle time and closure rates accurately"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or condition triggers the scheduling of a vendor meeting — is it recurring on a fixed schedule, initiated by a specific operational issue, or requested on an ad hoc basis?",
      "targets": ["Meeting Trigger"],
      "source_ids": ["C2"],
      "selection_reason": "C2 directly and cleanly addresses the workflow start event, which is unaddressed by any other candidate and critical for process modeling"
    },
    {
      "id": "Q2",
      "question": "Which roles from your organization typically attend the vendor meeting, and who holds primary responsibility for organizing it and producing the post-meeting summary?",
      "targets": ["Roles and Ownership"],
      "source_ids": ["C1", "C4"],
      "selection_reason": "C1 and C4 overlap substantially; this merged version captures both attendance and ownership in a single focused question, eliminating redundancy"
    },
    {
      "id": "Q3",
      "question": "What does the meeting summary look like as a finished output — is it a free-text email, a structured template, or a formal document — and who receives it?",
      "targets": ["Summary Output Format"],
      "source_ids": ["C5"],
      "selection_reason": "C5 specifically targets the summary artifact's format and distribution, which is distinct from the tool used to store notes; C6 is reserved for the storage/tool question"
    },
    {
      "id": "Q4",
      "question": "When action items are identified from the meeting, how are they recorded and assigned — do they include a designated owner, a due date, and a priority level, and if so, what tool or system is used to store this information?",
      "targets": ["Action Item Recording"],
      "source_ids": ["C8", "C3"],
      "selection_reason": "C8 covers the structure of action item capture while C3 addresses the storage tool; merging them avoids a separate question on tooling and keeps the focus on the action item subprocess"
    },
    {
      "id": "Q5",
      "question": "How is follow-up on action items currently conducted, and what happens when an item is not completed by its agreed deadline — is there a formal escalation path, an automated reminder, or does someone follow up manually?",
      "targets": ["Follow-up Mechanism"],
      "source_ids": ["C10", "C9"],
      "selection_reason": "C10 and C9 are complementary: C10 covers the routine follow-up method and frequency, C9 covers the exception path; combining them into one question avoids two closely related questions on the same subprocess"
    },
    {
      "id": "Q6",
      "question": "What criteria must be met for this workflow to be considered fully complete — for example, all action items marked closed, a final summary report approved, or some other condition?",
      "targets": ["Workflow Completion Criteria"],
      "source_ids": ["C12"],
      "selection_reason": "C12 uniquely addresses the process end event and closure definition, which is necessary for measuring workflow performance and defining automation boundaries"
    }
  ]
}
